async function compressedJSON(path){const r=await fetch(path);if(!r.ok)throw Error('Could not load '+path+' ('+r.status+')');const b=await r.arrayBuffer();const u=new Uint8Array(b);if(u[0]===31&&u[1]===139){if(!window.DecompressionStream)throw Error('This atlas needs a current browser with compressed-data support.');return JSON.parse(await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream('gzip'))).text());}return JSON.parse(new TextDecoder().decode(b));}
