async function renderBoundaries(){if(!atlas)return;const revision=++boundaryRevision;boundaryGroup.clearLayers();const chosen=[...document.querySelectorAll('#layerChecks input:checked')].map(x=>x.value);if(!chosen.length)return;$('boundaryNote').textContent='Loading selected boundaries…';try{for(let k=0;k<chosen.length;k++){const type=chosen[k];let collections;if(type==='SAL'){if(map.getZoom()<7&&!$('state').value){$('boundaryNote').textContent='Choose a state or zoom in to see locality boundaries.';continue;}const ss=$('state').value?[$('state').value]:[...new Set(filtered.filter(l=>map.getBounds().contains([l.lat,l.lon])).map(l=>l.s))];collections=await Promise.all(ss.map(s=>getGeo('SAL_'+s)));}else collections=[await getGeo(type)];if(revision!==boundaryRevision)return;const features=collections.flatMap(x=>x.features).filter(f=>boundsVisible(f)&&(!$('state').value||!f.properties.s||f.properties.s===$('state').value));L.geoJSON(features,{style:{color:PALETTE[k%PALETTE.length],weight:type==='SAL'?.7:1.6,fillOpacity:type==='SAL'?.03:.02},onEachFeature:(f,l)=>l.bindTooltip(esc(TYPES[type])+': '+esc(f.properties.n)+'<br>'+esc(f.properties.v))}).addTo(boundaryGroup);}if(revision===boundaryRevision)$('boundaryNote').textContent=chosen.map(t=>TYPES[t]+' '+shortVersion(t)).join(' · ');}catch(e){if(revision===boundaryRevision){$('boundaryNote').textContent='Boundary load failed. Toggle the layer to retry.';toast(e.message);}}}
