async function readRows(file){if(!file)throw Error('Choose a file first.');if(file.size>25*1024*1024)throw Error('Please use a file smaller than 25 MB.');const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false,raw:true});const sheet=wb.Sheets[wb.SheetNames[0]],matrix=XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:false});if(matrix.length<2)throw Error('The first worksheet needs headers and at least one data row.');if(matrix.length>10001)throw Error('Use up to 10,000 data rows per import.');const headers=matrix[0].map(x=>String(x).trim().toLowerCase().replace(/\s+/g,'_'));if(headers.some(x=>!x)||new Set(headers).size!==headers.length)throw Error('Every source column needs a unique, nonblank header.');return matrix.slice(1).filter(r=>r.some(x=>x!=='')).map((r,i)=>({...Object.fromEntries(headers.map((k,j)=>[k,r[j]??''])),_source_row:i+2}));}
const normalName=s=>String(s??'').trim().replace(/\s+/g,' ').toUpperCase();
function normalState(v){const s=normalName(v),m={'NEW SOUTH WALES':'NSW','VICTORIA':'VIC','QUEENSLAND':'QLD','SOUTH AUSTRALIA':'SA','WESTERN AUSTRALIA':'WA','TASMANIA':'TAS','NORTHERN TERRITORY':'NT','AUSTRALIAN CAPITAL TERRITORY':'ACT','OTHER':'OT','OTHER TERRITORIES':'OT'};return m[s]||s;}
function normalPC(v){const s=String(v??'').trim();return /^\d{1,4}$/.test(s)?s.padStart(4,'0'):s;}
function hasNumber(v){return String(v??'').trim()!==''&&Number.isFinite(Number(v));}
function ringResult(point,ring){let inside=false;const[x,y]=point;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const[a,b]=ring[i],[c,d]=ring[j];const cross=(x-a)*(d-b)-(y-b)*(c-a);if(Math.abs(cross)<1e-10&&x>=Math.min(a,c)-1e-10&&x<=Math.max(a,c)+1e-10&&y>=Math.min(b,d)-1e-10&&y<=Math.max(b,d)+1e-10)return 2;if(((b>y)!==(d>y))&&(x<(c-a)*(y-b)/(d-b)+a))inside=!inside;}return inside?1:0;}
function polygonResult(point,rings){const outer=ringResult(point,rings[0]);if(!outer)return 0;if(outer===2)return 2;for(let i=1;i<rings.length;i++){const hole=ringResult(point,rings[i]);if(hole===2)return 2;if(hole===1)return 0;}return 1;}
function geometryResult(point,g){if(g.type==='Polygon')return polygonResult(point,g.coordinates);if(g.type==='MultiPolygon'){let result=0;for(const p of g.coordinates)result=Math.max(result,polygonResult(point,p));return result;}if(g.type==='GeometryCollection')return Math.max(0,...g.geometries.map(x=>geometryResult(point,x)));return 0;}
function featureIndex(collection){const bins=new Map(),wide=[];for(const f of collection.features){const b=f.bbox;if(!b){wide.push(f);continue;}const x0=Math.floor(b[0]),x1=Math.floor(b[2]),y0=Math.floor(b[1]),y1=Math.floor(b[3]);if((x1-x0+1)*(y1-y0+1)>500){wide.push(f);continue;}for(let x=x0;x<=x1;x++)for(let y=y0;y<=y1;y++){const key=x+','+y;if(!bins.has(key))bins.set(key,[]);bins.get(key).push(f);}}return {bins,wide};}
async function indexedGeo(type){const collection=await getGeo(type);if(!geoIndexes.has(type))geoIndexes.set(type,featureIndex(collection));return geoIndexes.get(type);}
function pointMatches(index,lon,lat){return [...(index.bins.get(Math.floor(lon)+','+Math.floor(lat))||[]),...index.wide].filter(f=>{const b=f.bbox;return (!b||(lon>=b[0]&&lon<=b[2]&&lat>=b[1]&&lat<=b[3]))&&geometryResult([lon,lat],f.geometry)>0;});}
$('businessFile').onchange=async()=>{try{const rows=await readRows($('businessFile').files[0]);if(!rows.some(r=>'business_name'in r))throw Error('Use a business_name column. Download the template for the accepted location fields.');businessColumns=[...new Set(rows.flatMap(r=>Object.keys(r)))];businesses=rows.map((r,i)=>({source:r,id:i,status:'pending',out:{...r},lat:null,lon:null,salCodes:[]}));businessReady=false;$('enrichBusinesses').disabled=!atlas;$('businessImportStatus').textContent=rows.length.toLocaleString()+' source rows loaded. Select a matching method, then locate & enrich.';$('showBusinesses').disabled=true;$('exportBusinesses').disabled=false;$('bizNavCount').textContent='('+rows.length.toLocaleString()+')';renderBusinessTable();drawBusinesses();}catch(e){toast(e.message);$('businessImportStatus').textContent=e.message;}};
async function enrichBusinesses(){if(!atlas||!businesses.length)return;const btn=$('enrichBusinesses');btn.disabled=true;const selected=[...document.querySelectorAll('#businessLayers input:checked')].map(x=>x.value),allowFallback=document.querySelector('[name=matchMode]:checked').value==='locality';try{$('businessImportStatus').textContent='Loading locality boundaries for coordinate matching…';const salCollections=await Promise.all(Object.keys(STATE_NAMES).map(s=>getGeo('SAL_'+s))),salIndex=featureIndex({features:salCollections.flatMap(c=>c.features)});const layerIndexes={};for(let i=0;i<selected.length;i++){$('businessImportStatus').textContent='Preparing '+TYPES[selected[i]]+' ('+(i+1)+'/'+selected.length+')…';layerIndexes[selected[i]]=await indexedGeo(selected[i]);}const names=new Map();for(const l of atlas.localities){const k=stateAbbr(l.s)+':'+normalName(l.n);if(!names.has(k))names.set(k,[]);names.get(k).push(l);}
for(let i=0;i<businesses.length;i++){const b=businesses[i],r=b.source,state=normalState(r.state),postcode=normalPC(r.postcode);b.status='unmatched';b.lat=null;b.lon=null;b.salCodes=[];const out={...r,normalized_state:state,normalized_postcode:postcode,match_status:'unmatched',match_note:'No resolved location',geo_source:'ABS ASGS / AEC',geo_display_tolerance_m:25,enriched_date:new Date().toISOString().slice(0,10)};const provided=String(r.latitude??'').trim()!==''||String(r.longitude??'').trim()!=='';let matched=[];
if(provided){if(hasNumber(r.latitude)&&hasNumber(r.longitude)&&+r.latitude>=-55&&+r.latitude<=-9&&+r.longitude>=90&&+r.longitude<=170){b.lat=+r.latitude;b.lon=+r.longitude;matched=pointMatches(salIndex,b.lon,b.lat);if(matched.length){b.status=matched.length===1?'coordinate':'unmatched';out.match_status=matched.length===1?'coordinate_matched':'boundary_multiple_localities_review';out.match_note='Point-in-polygon on 25 m simplified statistical boundaries; source coordinate accuracy not independently verified';const states=[...new Set(matched.map(f=>stateAbbr(f.properties.s)))];out.matched_states=states.join('; ');if(state&&!states.includes(state)){b.status='unmatched';out.match_status='coordinate_state_conflict_review';out.match_note+='; supplied state conflicts with matched state';}}else{out.match_status='coordinate_outside_locality_review';out.match_note='Valid numeric coordinates have no displayed Australian locality match';}}else{out.match_status='invalid_coordinate_review';out.match_note='Latitude/longitude missing as a pair or outside plausible Australian extent';}}
else if(allowFallback){let candidates=names.get(state+':'+normalName(r.locality))||[];if(postcode)candidates=candidates.filter(l=>(l.r.POA||[]).includes(postcode));out.candidate_locality_codes=candidates.map(l=>l.c).join('; ');if(candidates.length===1){const loc=candidates[0];b.lat=loc.lat;b.lon=loc.lon;b.status='approximate';b.salCodes=[loc.c];out.match_status='approximate_locality_representative_point';out.match_note='Exact locality+state match'+(postcode?' narrowed by ABS postal-area association':'')+'; not a premise geocode';out.SAL_codes=loc.c;out.SAL_names=loc.n;out.SAL_versions='ASGS Edition 4 (2026)';out.possible_SA1_codes=(loc.r.SA1||[]).join('; ');for(const t of selected){out[t+'_codes']=(loc.r[t]||[]).join('; ');out[t+'_names']=(loc.r[t]||[]).map(c=>geoName(t,c)).join('; ');out[t+'_versions']=[...new Set((loc.r[t]||[]).map(c=>atlas.geographies[t]?.[c]?.v||shortVersion(t)))].join('; ');}out.geographic_method='Whole-locality area associations; multiple regions retained';}else{out.match_status=candidates.length?'ambiguous_locality_review':'unmatched_locality_review';out.match_note=candidates.length?'More than one exact locality candidate; no point assigned':'No exact locality/state/postal-area candidate; no point assigned';}}
else{out.match_status='missing_coordinates';out.match_note='Coordinates-only mode; source row retained without a location';}
if(provided&&b.lat!==null){b.salCodes=matched.map(f=>f.properties.c);out.SAL_codes=b.salCodes.join('; ');out.SAL_names=matched.map(f=>f.properties.n).join('; ');out.SAL_versions=[...new Set(matched.map(f=>f.properties.v))].join('; ');out.geographic_method='Point-in-polygon; 25 m simplified display geometry';for(const t of selected){const matches=pointMatches(layerIndexes[t],b.lon,b.lat);out[t+'_codes']=matches.map(f=>f.properties.c).join('; ');out[t+'_names']=matches.map(f=>f.properties.n).join('; ');out[t+'_versions']=[...new Set(matches.map(f=>f.properties.v))].join('; ');}out.possible_SA1_codes=[...new Set(b.salCodes.flatMap(c=>localityByCode[c]?.r.SA1||[]))].join('; ');}
out.mapped_latitude=b.lat;out.mapped_longitude=b.lon;const overlayKeys=b.status==='approximate'?b.salCodes.flatMap(c=>(localityByCode[c]?.r.POA||[]).map(pc=>stateAbbr(localityByCode[c].s)+':'+pc)):matched.flatMap(f=>String(out.POA_codes||'').split('; ').filter(Boolean).map(pc=>stateAbbr(f.properties.s)+':'+pc));const supplements=[...new Set(overlayKeys)].map(k=>locus[k]).filter(Boolean);out.locus_postal_keys=[...new Set(supplements.map(x=>x.key))].join('; ');out.locus_mosaic_labels=[...new Set(supplements.map(x=>x.mosaic).filter(Boolean))].join('; ');out.locus_helix_personas=[...new Set(supplements.map(x=>x.helix).filter(Boolean))].join('; ');out.locus_seifa_deciles=[...new Set(supplements.map(x=>x.seifa).filter(x=>x!=null))].join('; ');out.locus_association_note='Supplied postcode context; commercial/SEIFA vintage unknown; not an individual classification';b.out=out;if(i%25===0){$('businessImportStatus').textContent='Enriching row '+(i+1).toLocaleString()+' of '+businesses.length.toLocaleString()+'…';await new Promise(r=>setTimeout(r,0));}}
businessReady=true;$('showBusinesses').disabled=false;$('exportBusinesses').disabled=false;$('businessImportStatus').textContent='Finished. All '+businesses.length.toLocaleString()+' source rows retained. Review match status before using locations.';renderBusinessTable();drawBusinesses();toast('List enriched. Export includes unresolved rows and matching methods.');}catch(e){$('businessImportStatus').textContent='Enrichment stopped: '+e.message+' You can export the current rows and retry.';toast(e.message);}finally{btn.disabled=false;}}
$('enrichBusinesses').onclick=enrichBusinesses;
function renderBusinessTable(){const q=$('businessQuery').value.trim().toLowerCase(),st=$('businessStatus').value,s=$('businessState').value;businessFiltered=businesses.filter(b=>(!q||[b.source.business_name,b.source.industry,b.source.service_tags].join(' ').toLowerCase().includes(q))&&(!st||b.status===st)&&(!s||normalState(b.source.state)===s));const counts={coordinate:0,approximate:0,unmatched:0,pending:0};for(const b of businesses)counts[b.status]++;$('businessSummary').textContent=businesses.length?businesses.length.toLocaleString()+' rows · '+counts.coordinate.toLocaleString()+' coordinate matches': 'Your list will appear here';const coverage=Object.entries(businesses.reduce((a,b)=>{const s=normalState(b.source.state)||'Unknown';a[s]=(a[s]||0)+1;return a;},{})).map(([s,n])=>s+': '+n.toLocaleString()).join(' · ');$('businessCoverage').textContent=businesses.length?counts.approximate+' approximate · '+counts.unmatched+' unmatched / review · '+counts.pending+' pending | Source-state coverage: '+coverage:'';$('businessRows').innerHTML=businessFiltered.length?businessFiltered.slice(0,250).map(b=>'<tr><td><strong>'+esc(b.source.business_name||'Unnamed business')+'</strong><small>'+esc(b.source.industry||b.source.service_tags||b.source.business_id||'')+'</small></td><td>'+esc([b.source.street_address,b.source.locality,b.source.postcode].filter(Boolean).join(', '))+'</td><td>'+esc(normalState(b.source.state))+'</td><td><span class="badge '+(b.status==='approximate'?'warn':b.status==='unmatched'?'bad':'')+'">'+esc(b.out.match_status||'pending')+'</span></td><td>'+esc(b.out.SAL_names||'Unresolved')+'<small>'+esc(b.out.LGA_names||'')+'</small></td></tr>').join(''):'<tr><td colspan="5" class="empty-state">'+(businesses.length?'No rows match these list filters.':'No businesses imported. Your source rows will remain available, including unmatched records.')+'</td></tr>';$('businessFootnote').textContent=businesses.length?'Showing '+Math.min(businessFiltered.length,250)+' of '+businessFiltered.length.toLocaleString()+' filtered records. Export includes every filtered row. Source-state counts measure this list’s coverage, not national directory completeness.':'';}
function drawBusinesses(){businessGroup.clearLayers();if(!businessReady)return;const visibleCodes=new Set(filtered.map(l=>l.c));let count=0;for(const b of businessFiltered){if(b.lat===null||!map.getBounds().pad(.1).contains([b.lat,b.lon]))continue;if(!b.salCodes.some(c=>visibleCodes.has(c)))continue;count++;if(count>2500)continue;L.circleMarker([b.lat,b.lon],{radius:7,weight:2,color:'#fff',fillColor:b.status==='coordinate'?'#dd7354':b.status==='approximate'?'#c5a04c':'#a44f4f',fillOpacity:.95}).bindPopup('<div class="biz-popup"><h3>'+esc(b.source.business_name)+'</h3><p>'+esc(b.source.locality)+' · '+esc(b.source.state)+'</p><p>'+esc(b.out.match_status)+'</p><p>'+esc(b.out.match_note)+'</p><p>'+esc(b.out.LGA_names||'')+'</p></div>').addTo(businessGroup);}if(count>2500)$('mapStatus').textContent='First 2,500 business points shown · zoom or filter';}
for(const id of ['businessQuery','businessStatus','businessState'])$(id).oninput=()=>{renderBusinessTable();drawBusinesses();};
$('showBusinesses').onclick=()=>{showPage('explore');const points=businessFiltered.filter(b=>b.lat!==null&&b.salCodes.length).map(b=>[b.lat,b.lon]);if(points.length)map.fitBounds(points,{padding:[55,55],maxZoom:13});else toast('No resolved business points to display. Review matching status.');};$('exportBusinesses').onclick=()=>exportCSV(businessFiltered.map(b=>b.out),'Locus_enriched_businesses.csv');
function expectedVersion(type,code){return atlas.geographies[type]?.[code]?.v||'';}
function validVersion(type,code,version){const expected=expectedVersion(type,code);return version===expected||(type!=='FED'&&String(version)===shortVersion(type));}
$('overlayFile').onchange=async()=>{try{if(!atlas)throw Error('Wait for geography to finish loading.');const rows=await readRows($('overlayFile').files[0]);customReview=rows.map(r=>{const t=String(r.geography_type||'').trim().toUpperCase(),c=String(r.geography_code||'').trim(),v=String(r.geography_version||'').trim();let reason='';if(!TYPES[t])reason='Unknown geography type';else if(!atlas.geographies[t]?.[c])reason='Unknown geography code';else if(!validVersion(t,c,v))reason='Boundary version mismatch; expected '+expectedVersion(t,c);else if(!String(r.metric||'').trim())reason='Missing metric';else if(String(r.value??'').trim()===''&&!String(r.category??'').trim())reason='Supply a numeric value or category';else if(String(r.value??'').trim()!==''&&!Number.isFinite(Number(r.value)))reason='Value is not numeric';return {...r,geography_type:t,geography_code:c,geography_version:v,metric:String(r.metric||'').trim(),category:String(r.category||'').trim(),value:String(r.value??'').trim(),import_status:reason?'rejected':'accepted',import_reason:reason};});const seen=new Set();for(const r of customReview){const key=[r.geography_type,r.geography_code,r.geography_version,r.metric].join('|');if(r.import_status==='accepted'&&seen.has(key)){r.import_status='rejected';r.import_reason='Duplicate geography/version/metric key in this import';}if(r.import_status==='accepted')seen.add(key);}customRows=customReview.filter(r=>r.import_status==='accepted');const metrics=[...new Set(customRows.map(r=>r.metric))].sort();options($('customMetric'),metrics.map(m=>[m,m]),'None');$('customControls').hidden=!customRows.length;$('exportOverlayReview').hidden=false;$('overlayStatus').textContent=customRows.length+' accepted; '+(rows.length-customRows.length)+' rejected. '+metrics.length+' metrics available in Explore. This import replaces the previous indexed overlay.';filterPlaces();toast('Overlay import checked. Use “Your indexed overlay” in Explore.');}catch(e){$('overlayStatus').textContent=e.message;toast(e.message);}};
$('customMetric').onchange=()=>{const cats=[...new Set(customRows.filter(r=>r.metric===$('customMetric').value&&r.category).map(r=>r.category))].sort();options($('customCategory'),cats.map(c=>[c,c]),'All categories');filterPlaces();};for(const k of ['customCategory','customMin','customMax'])$(k).oninput=filterPlaces;$('exportOverlayReview').onclick=()=>exportCSV(customReview,'Locus_overlay_import_review.csv');
function validCoordinates(g){if(!g)return false;if(g.type==='GeometryCollection')return g.geometries.every(validCoordinates);if(!['Point','MultiPoint','LineString','MultiLineString','Polygon','MultiPolygon'].includes(g.type))return false;let valid=true;const walk=c=>{if(!Array.isArray(c)||!c.length){valid=false;return;}if(typeof c[0]==='number'){if(c.length<2||!Number.isFinite(c[0])||!Number.isFinite(c[1])||Math.abs(c[0])>180||Math.abs(c[1])>90)valid=false;}else c.forEach(walk);};walk(g.coordinates);return valid;}
$('geojsonFile').onchange=async()=>{try{const file=$('geojsonFile').files[0];if(!file)return;if(file.size>20*1024*1024)throw Error('Use a GeoJSON file smaller than 20 MB.');const data=JSON.parse(await file.text());if(data.crs)throw Error('Remove legacy CRS declarations after converting the file to WGS84 longitude/latitude.');const features=data.type==='FeatureCollection'?data.features:data.type==='Feature'?[data]:[{type:'Feature',properties:{},geometry:data}];if(!features.length||features.some(f=>!validCoordinates(f.geometry)))throw Error('Use valid WGS84 Point, LineString or Polygon geometries, including multi-geometries.');const layer=L.geoJSON({type:'FeatureCollection',features},{style:{color:'#875bab',weight:2,fillOpacity:.14},pointToLayer:(f,ll)=>L.circleMarker(ll,{radius:7,color:'#875bab'}),onEachFeature:(f,l)=>l.bindPopup('<strong>Uploaded feature</strong><br>'+Object.entries(f.properties||{}).slice(0,20).map(([k,v])=>'<b>'+esc(k)+'</b>: '+esc(typeof v==='object'?JSON.stringify(v):v)).join('<br>'))});customShapeGroup.clearLayers();customShapeGroup.addLayer(layer);$('showCustomShapes').checked=true;customShapeGroup.addTo(map);$('geojsonStatus').textContent=features.length.toLocaleString()+' uploaded features · visual overlay only · session local.';showPage('explore');if(layer.getBounds().isValid())map.fitBounds(layer.getBounds(),{maxZoom:13,padding:[50,50]});}catch(e){$('geojsonStatus').textContent=e.message;toast(e.message);}};
$('showCustomShapes').onchange=()=>{$('showCustomShapes').checked?customShapeGroup.addTo(map):map.removeLayer(customShapeGroup);};$('clearCustom').onclick=()=>{customRows=[];customReview=[];customShapeGroup.clearLayers();$('customControls').hidden=true;$('customMetric').value='';$('exportOverlayReview').hidden=true;$('overlayStatus').textContent='No custom index loaded.';$('geojsonStatus').textContent='No custom shapes loaded.';filterPlaces();};
$('downloadNational').onclick=async()=>{const btn=$('downloadNational');btn.disabled=true;try{const r=await fetch('downloads/national-download.json');if(!r.ok)throw Error('Download manifest unavailable.');const manifest=await r.json(),parts=[];for(let i=0;i<manifest.parts.length;i++){$('downloadProgress').textContent='Preparing workbook · part '+(i+1)+' of '+manifest.parts.length;const p=await fetch('downloads/'+manifest.parts[i]);if(!p.ok)throw Error('Workbook part failed to load. Please retry.');parts.push(await p.arrayBuffer());}const blob=new Blob(parts,{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});if(manifest.bytes&&blob.size!==manifest.bytes)throw Error('Workbook size check failed. Please retry.');saveBlob(blob,manifest.filename);$('downloadProgress').textContent='Download ready · '+(blob.size/1024/1024).toFixed(1)+' MB. Your browser handles saving the file.';}catch(e){$('downloadProgress').textContent=e.message;}finally{btn.disabled=false;}};
async function start(){try{const [a,ld,recommendations]=await Promise.all([compressedJSON('data/atlas.json.gz'),compressedJSON('data/locus.json.gz'),fetch('data/recommendations.json').then(r=>{if(!r.ok)throw Error('Recommendations unavailable');return r.json();})]);atlas=a;for(const loc of atlas.localities){loc.c=String(loc.c);loc.s=String(loc.s);localityByCode[loc.c]=loc;}locus=Object.fromEntries((Array.isArray(ld.records)?ld.records:Object.values(ld.records)).map(r=>[r.key||r.state+':'+r.postcode,r]));for(const [c,s]of Object.entries(STATE_NAMES)){$('state').add(new Option(s,c));$('businessState').add(new Option(s,s));}$('localityTotal').textContent=atlas.localities.length.toLocaleString();$('nationalStats').textContent=(atlas.meta?.locality_count||15377).toLocaleString()+' locality records · full crosswalk, sources & QA';$('recommendations').innerHTML=recommendations.map((r,i)=>'<article class="recommendation"><span class="number">'+String(i+1).padStart(2,'0')+' / '+esc(r.priority)+'</span><h3>'+esc(r.title)+'</h3><p>'+esc(r.use)+'</p><p class="help">'+esc(r.grain)+'. '+esc(r.caution)+'</p><a class="text-link" href="'+esc(r.url)+'" target="_blank" rel="noopener">'+esc(r.source)+' ↗</a></article>').join('');fillGeoFilter();fillSegments();filterPlaces();$('loading').hidden=true;if(businesses.length)$('enrichBusinesses').disabled=false;getGeo('STE').then(data=>{L.geoJSON(data,{interactive:false,style:themeMapStyle()}).addTo(baseGroup);}).catch(e=>toast('Base outline could not load; markers remain available. '+e.message));showPage(location.hash.slice(1)||'explore');}catch(e){$('loading').innerHTML='<strong>Atlas could not finish loading</strong><span>'+esc(e.message)+'</span><button class="primary" onclick="location.reload()">Retry loading</button>';toast(e.message);}}
start();
